# NumberInput NumberInput ## Быстрый старт Быстрый старт ```tsx
import React, { useState } from 'react';
import { NumberInput } from '@salutejs/sdds-finai';

export function App() {
    const [value, setValue] = useState(5);

    return (
        <div>
            <NumberInput
                value={value}
                min={0}
                max={10}
                width={188}
                onChange={(_, newValue) => setValue(newValue)}
            />
        </div>
    );
}
```

## Управление внешним видом Управление внешним видом Внешний вид компонента зависит от свойств  `view`  и  `size` : ```tsx
import React from 'react';
import { NumberInput } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', gap: '1rem', flexDirection: 'column' }}>
            <NumberInput value={5} width={188} view="default" />
            <NumberInput value={5} width={188} view="secondary" />
            <NumberInput value={5} width={188} view="accent" />
            <NumberInput value={5} width={188} view="clear" />
        </div>
    );
}
```

